// Generated by Claude (AI-assisted), adapted from the persistent worker of
// https://github.com/cauli/lean4-wasm-in-browser (Apache-2.0).
//
// Runs Lean, compiled to WebAssembly, inside a Web Worker for the book's
// exercise editors.  The page sends one `boot` message naming where the Lean
// runtime lives and the import header the exercises share; the worker fetches
// what it needs, starts Lean once, imports those modules once, and then
// answers `compile` messages with Lean's diagnostics.  Lean keeps the imported
// environment between compiles, so only the first one pays for the import.
// `info`, `complete` and `resolve` messages ask what an editor shows at a
// position (goals, hover text, completions), from what Lean recorded while
// compiling the code last.
//
// The runtime may live on another origin (a CDN).  A worker may not start
// another worker from a cross-origin script, and Lean's thread pool does just
// that with `lean.js`, so `lean.js` is fetched and run from a Blob URL, which
// belongs to this origin.

'use strict';

let moduleReady = false;
let collecting = null; // diagnostics of the compile in progress, one JSON object per line
let uncaught = null; // what Lean printed about an exception that ended the compile
let debug = false; // forward the runtime's own output to the page console

function post(type, data) {
  self.postMessage({ type, ...data });
}

// The runtime prints its own tracing; only Lean's JSON diagnostics matter here.
function onOutput(text) {
  if (collecting && text.startsWith('{')) {
    try { collecting.push(JSON.parse(text)); return; } catch (e) { /* not a diagnostic */ }
  }
  if (uncaught) uncaught.push(text);
  const progress = /\[DEBUG:PROGRESS\]\s*(\d+)\/(\d+)/.exec(text);
  if (progress) post('import_progress', { loaded: +progress[1], total: +progress[2] });
  else if (debug) post('log', { text });
}

// Start with the largest shared memory the device grants.  Allocating it does
// not touch it, so a large initial size costs nothing until Lean uses it.
function pickWasmMemory() {
  const PAGE = 65536;
  for (const mb of [2048, 1536, 1024, 768]) {
    try {
      const memory = new WebAssembly.Memory({ initial: (mb * 1024 * 1024) / PAGE, maximum: 65536, shared: true });
      return { wasmMemory: memory, INITIAL_MEMORY: mb * 1024 * 1024 };
    } catch (e) { /* try smaller */ }
  }
  return {};
}

function mkdirp(FS, path) {
  let current = '';
  for (const part of path.split('/').filter(Boolean)) {
    current += '/' + part;
    try { FS.mkdir(current); } catch (e) { /* exists */ }
  }
}

function mkLeanString(str) {
  const ptr = Module.stringToNewUTF8(str);
  const obj = Module._lean_mk_string(ptr);
  Module._free(ptr);
  return obj;
}

// The library files for the layers the book imports from.  The runtime's file
// list names every `.olean` it ships; the book's imports reach into nearly all
// of Init, Std and Lean, so those layers are loaded whole, as the playground
// does for `import Lean`.
const LAYERS = new Set(['Init', 'Std', 'Lean']);

function layerFiles(fileList) {
  return fileList.filter((p) => p.endsWith('.olean') && LAYERS.has(p.split('/')[0].replace(/\.olean$/, '')));
}

const CACHE_PREFIX = 'sfl-lean-';

// This runtime version's browser cache.  Caches of other versions are deleted:
// each holds a whole library, hundreds of MB that no page asks for again once
// the book points at a newer runtime.
async function openCache(version) {
  const name = CACHE_PREFIX + version;
  try {
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== name) await caches.delete(key);
    }
    return await caches.open(name);
  } catch (e) {
    return null; // no Cache API here; download every time
  }
}

async function cachedFetch(cache, url) {
  const hit = cache && await cache.match(url);
  if (hit) return hit;
  const response = await fetch(url);
  if (response.ok && cache) {
    try { await cache.put(url, response.clone()); } catch (e) { /* storage full; still usable */ }
  }
  return response;
}

// The library as packs (web/cloudflare/pack_library.py): a few gzip files,
// fetched four at a time and inflated with the browser's own decompressor.
// Each file is a view into its inflated pack, so nothing is copied.
async function fetchPacks(runtimeBase, q, index, cache) {
  const files = [];
  const total = index.packs.reduce((n, p) => n + p.compressedBytes, 0);
  let bytes = 0;
  const queue = [...index.packs];
  async function worker() {
    while (queue.length) {
      const pack = queue.shift();
      const url = runtimeBase + pack.file + q;
      const response = await cachedFetch(cache, url);
      if (!response.ok) throw new Error(pack.file + ': HTTP ' + response.status);
      const inflated = (await response.blob()).stream().pipeThrough(new DecompressionStream('gzip'));
      const raw = new Uint8Array(await new Response(inflated).arrayBuffer());
      if (raw.byteLength !== pack.bytes) {
        if (cache) await cache.delete(url);
        throw new Error(pack.file + ' arrived damaged; reload to download it again');
      }
      for (const [path, offset, length] of pack.entries) {
        files.push({ path, data: raw.subarray(offset, offset + length) });
      }
      bytes += pack.compressedBytes;
      post('library_progress', { done: bytes, total, bytes });
    }
  }
  await Promise.all(Array.from({ length: 4 }, worker));
  return files;
}

// The library file by file, for runtimes without packs (a local dev runtime,
// say).  An `.olean` may have siblings: `.olean.server` (docstrings, for
// hovers and completions) and `.ir` and `.ir.sig` (the compiled code `#eval`
// runs); a module without them answers 404, which is fine.
async function fetchFiles(libBase, paths, cache) {
  const wanted = paths.flatMap((p) => [p, p + '.server', p.replace(/\.olean$/, '.ir'), p.replace(/\.olean$/, '.ir.sig')]);
  const files = [];
  let done = 0;
  let bytes = 0;
  const queue = [...wanted];
  async function worker() {
    while (queue.length) {
      const path = queue.shift();
      const response = await cachedFetch(cache, libBase + path);
      if (response.ok) {
        const data = new Uint8Array(await response.arrayBuffer());
        files.push({ path, data });
        bytes += data.byteLength;
      }
      done++;
      if (done % 50 === 0 || done === wanted.length) {
        post('library_progress', { done, total: wanted.length, bytes });
      }
    }
  }
  await Promise.all(Array.from({ length: 16 }, worker));
  return files;
}

async function fetchLibrary(runtimeBase, q, cache) {
  const packs = typeof DecompressionStream === 'function'
    && await fetch(runtimeBase + 'library-packs.json' + q).catch(() => null);
  if (packs && packs.ok) {
    if (debug) post('log', { text: 'library: from packs' });
    return fetchPacks(runtimeBase, q, await packs.json(), cache);
  }
  const list = await fetch(runtimeBase + 'lean-lib-files.json' + q);
  if (!list.ok) throw new Error('lean-lib-files.json: HTTP ' + list.status);
  return fetchFiles(runtimeBase + 'lean-lib/', layerFiles(await list.json()), cache);
}

// A Blob URL of `name` (lean.js or lean.wasm), from the cache or the network.
async function fetchBlobUrl(runtimeBase, name, q, cache, type) {
  const response = await cachedFetch(cache, runtimeBase + name + q);
  if (!response.ok) throw new Error(name + ': HTTP ' + response.status);
  return URL.createObjectURL(new Blob([await response.blob()], { type }));
}

async function boot({ runtimeBase, version, debug: wantDebug }) {
  debug = !!wantDebug;
  const q = version ? '?v=' + encodeURIComponent(version) : '';
  const cache = await openCache(version || 'unversioned');
  // lean.wasm, about 100 MB, downloads alongside the library instead of after
  // it, when Emscripten's loader would ask for it; the loader then reads it
  // from memory.  Failures surface where they are awaited.
  const wasm = fetchBlobUrl(runtimeBase, 'lean.wasm', q, cache, 'application/wasm');
  const glue = fetchBlobUrl(runtimeBase, 'lean.js', q, cache, 'text/javascript');
  for (const p of [wasm, glue]) p.catch(() => {});
  const files = await fetchLibrary(runtimeBase, q, cache);
  if (debug) post('log', { text: `library: ${files.length} files` });
  post('importing', {});
  const [wasmUrl, glueUrl] = await Promise.all([wasm, glue]);

  await new Promise((resolve, reject) => {
    self.Module = {
      ...pickWasmMemory(),
      locateFile: (path) => (path === 'lean.wasm' ? wasmUrl : runtimeBase + path + q),
      mainScriptUrlOrBlob: glueUrl,
      print: onOutput,
      printErr: onOutput,
      noInitialRun: true,
      preRun: [function () {
        const FS = Module.FS;
        Module.ENV.LEAN_PATH = '/lib/lean';
        // Lean finds its library relative to its own executable, /bin/lean.
        for (const dir of ['/bin', '/lib/lean', '/workspace']) mkdirp(FS, dir);
        for (const { path, data } of files) {
          const full = '/lib/lean/' + path;
          mkdirp(FS, full.slice(0, full.lastIndexOf('/')));
          // The file system keeps `data` itself rather than a copy.
          FS.writeFile(full, data, { canOwn: true });
        }
        files.length = 0;
        FS.chdir('/workspace');
      }],
      onRuntimeInitialized() {
        try {
          Module._lean_initialize_runtime_module();
          Module._lean_initialize();
          Module._lean_io_mark_end_initialization();
          if (Module._lean_init_task_manager) Module._lean_init_task_manager();
          if (Module._lean_enable_initializer_execution) Module._lean_enable_initializer_execution();
          const sp = Module._lean_init_search_path();
          if ((Module.getValue(sp + 7, 'i8') & 0xff) !== 0) throw new Error('lean_init_search_path failed');
          // The runtime is linked with EXIT_RUNTIME=1 and this worker never
          // runs main(), so without a keepalive reference the first time a
          // Lean thread hands work back to this thread the runtime exits and
          // closes stdout/stderr, and every later compile fails.  Runtimes
          // built before the fork exported this function lack it.
          if (Module._emscripten_runtime_keepalive_push) Module._emscripten_runtime_keepalive_push();
          // Threads started from here on get the compiled module from this
          // one, so the downloaded bytes can go.
          URL.revokeObjectURL(wasmUrl);
          moduleReady = true;
          resolve();
        } catch (e) { reject(e); }
      },
      onAbort: (what) => reject(new Error('Lean aborted: ' + what)),
    };
    importScripts(glueUrl);
  });
}

// Errors from the one-time check of each context, which Lean prints only
// then, keyed by a hash of the context's text.
const contextErrors = new Map();

function hashText(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193);
  return (h >>> 0).toString(16) + ':' + text.length;
}

// Check `code`, which continues `context` (the material an exercise builds
// on) when one is given.  A runtime with `lean_wasm_compile_with_context`
// checks the context once and then only `code`; an older one gets the whole
// text every time.  `codeLine` is the line of Lean's input on which `code`
// starts, for renumbering its messages.
function compile(code, context) {
  if (!moduleReady) return { ok: false, error: 'Lean is not ready' };
  const withContext = context != null && typeof Module._lean_wasm_compile_with_context === 'function';
  const file = mkLeanString('/workspace/Exercise.lean');
  collecting = [];
  const t0 = performance.now();
  try {
    const res = withContext
      ? Module._lean_wasm_compile_with_context(mkLeanString(context), mkLeanString(code), file)
      : Module._lean_wasm_compile(mkLeanString(context == null ? code : context + code), file);
    // The result is an IO action's: constructor tag 0 (the byte at offset 7)
    // means it returned, whatever the diagnostics say; anything else means it
    // threw, and Lean prints the exception when asked.
    const tag = Module.getValue(res + 7, 'i8') & 0xff;
    const elapsed = () => performance.now() - t0;
    if (tag !== 0) {
      uncaught = [];
      try { Module._lean_io_result_show_error(res); } catch (e) { /* nothing more to say */ }
      const error = uncaught.filter((l) => !/^\s*\[/.test(l)).join('\n') || 'Lean stopped with an exception';
      return { ok: false, error, messages: collecting, elapsed: elapsed() };
    }
    if (!withContext) {
      const codeLine = context == null ? 1 : context.split('\n').length;
      return { ok: true, messages: collecting, codeLine, elapsed: elapsed() };
    }
    const key = hashText(context);
    const fresh = collecting.filter((m) => m.context);
    if (fresh.length || !contextErrors.has(key)) {
      contextErrors.set(key, fresh.filter((m) => m.severity === 'error'));
    }
    const messages = collecting.filter((m) => !m.context).concat(contextErrors.get(key));
    return { ok: true, messages, codeLine: 1, elapsed: elapsed() };
  } catch (e) {
    return { ok: false, error: (e && e.message) || String(e), messages: collecting };
  } finally {
    collecting = null;
    uncaught = null;
  }
}

// The code the runtime compiled last, which its position queries are about,
// and that compile's result.
let lastCompiled = null;

function compiledKey(code, context) {
  return (context == null ? '' : hashText(context)) + '\n' + code;
}

// Compile `code` unless it is what the runtime compiled last.
function ensureCompiled(code, context) {
  const key = compiledKey(code, context);
  if (lastCompiled && lastCompiled.key === key) return lastCompiled.result;
  const result = compile(code, context);
  lastCompiled = { key, result };
  return result;
}

// Run a position query and return the one JSON object it prints, or null
// when the runtime lacks it or it threw.
function query(name, ...args) {
  const fn = Module[name];
  if (typeof fn !== 'function' || !moduleReady) return null;
  collecting = [];
  try {
    const res = fn(...args);
    if ((Module.getValue(res + 7, 'i8') & 0xff) !== 0) return null;
    return collecting[collecting.length - 1] || null;
  } catch (e) {
    return null;
  } finally {
    collecting = null;
  }
}

// Positions are Lean's: 1-based lines and codepoint columns, in `code`.
function answer(msg) {
  if (msg.type === 'compile') return ensureCompiled(msg.code, msg.context);
  if (msg.type === 'info') {
    const result = ensureCompiled(msg.code, msg.context);
    return { result, info: result.ok ? query('_lean_wasm_info_at', msg.line, msg.column) : null };
  }
  if (msg.type === 'complete') {
    const result = ensureCompiled(msg.code, msg.context);
    return { result, completions: result.ok ? query('_lean_wasm_complete', msg.line, msg.column) : null };
  }
  if (msg.type === 'resolve') {
    return { item: query('_lean_wasm_resolve_completion', msg.index) };
  }
  return {};
}

self.onmessage = async (event) => {
  const msg = event.data || {};
  if (msg.type === 'boot') {
    try {
      await boot(msg);
      // Import the modules now, while the reader is still reading, so the
      // first Run elaborates only the exercise.
      post('importing', {});
      const warm = compile(msg.header);
      post('ready', {
        ok: warm.ok, elapsed: warm.elapsed, error: warm.error,
        queries: typeof Module._lean_wasm_info_at === 'function',
      });
    } catch (e) {
      post('failed', { error: (e && e.message) || String(e) });
    }
  } else if (msg.id != null) {
    post('answer', { id: msg.id, ...answer(msg) });
  }
};
